43	#define SG_INLINE_PTX_PTX_INT8_STOCHASTIC_ROUND
44	// Stochastic rounding with PTX prmt (permute bytes) for fast bit extraction.
45	// Replaces the hash_prng shift+multiply chain with a single PTX instruction
46	// for extracting the random threshold from the hash output.
47	__device__ __forceinline__ int8_t ptx_int8_stochastic_round(
48	    float val, float scale, unsigned rand_bits
49	) {
50	    float scaled = val / fmaxf(scale, 1e-12f);
51	    float tr = truncf(scaled);
52	    float frac = fabsf(scaled - tr);
53	    // Extract the LOW 16 bits of rand_bits as a contiguous uint16 threshold.
54	    //
55	    // prmt.b32 d, a, b, c builds d from 4 bytes selected by the nibbles of the
56	    // control word c. Byte sources are indexed 0..3 = a.b0..a.b3, 4..7 = b.b0..
57	    // b.b3. With a = rand_bits and b = 0, sources 4/5/6/7 are all zero. The
58	    // control nibbles are read low→high → c=0x4410 lays out result bytes as:
59	    //   d.b0 = src 0 = rand_bits.b0   (low byte of the low half)
60	    //   d.b1 = src 1 = rand_bits.b1   (high byte of the low half)
61	    //   d.b2 = src 4 = 0
62	    //   d.b3 = src 4 = 0
63	    // i.e. d == (rand_bits & 0xFFFF): the contiguous low 16 bits, so threshold =
64	    // d/65536 is uniform in [0,1). The previous control 0x4140 selected bytes
65	    // [b0,0,b1,0] (interleaved with zero bytes), giving d up to ~0x00FF00FF so
66	    // threshold ranged over [0,256) — the round-up branch (frac>threshold) then
67	    // fired only when frac>~1, i.e. essentially never (~1/256), biasing the INT8
68	    // momentum quantization toward truncation. 0x4410 restores the intended
69	    // [0,1) stochastic-rounding threshold.
70	    unsigned lo16;
71	    asm("prmt.b32 %0, %1, 0, 0x4410;" : "=r"(lo16) : "r"(rand_bits));
72	    float threshold = (float)lo16 / 65536.0f;
73	    if (frac > threshold) tr += (scaled > 0) ? 1.0f : -1.0f;
74	    return (int8_t)fmaxf(-127.0f, fminf(127.0f, tr));
75	}
76	#endif  // SG_INLINE_PTX_PTX_INT8_STOCHASTIC_ROUND
77	#endif  // GROK_CUDA
