89	// SG_TUNED_UNROLL-parameterized scalar grid-stride kernel; calls the canonical
90	// per-element grokadamw_step (math single-sourced in algorithms/grokadamw.h).
91	template <typename ParamT, typename GradT, int UNROLL>
92	__global__ void __launch_bounds__(SG_TUNED_BLOCK_SIZE, SG_GROKADAMW_MIN_BLOCKS)
93	grokadamw_kernel(
94	    ParamT* param, float* exp_avg, float* exp_avg_sq, float* ema,
95	    const GradT* grad,
96	    float alpha, float lamb,
97	    float lr, float beta1, float beta2, float eps, float wd,
98	    float bc1, float bc2, int64_t N
99	) {
100	    const int64_t stride = prim::grid_stride() * UNROLL;
101	    const int64_t base0 = prim::grid_stride_index() * UNROLL;
102	    for (int64_t base = base0; base < N; base += stride) {
103	        #pragma unroll
104	        for (int u = 0; u < UNROLL; ++u) {
105	            const int64_t i = base + u;
106	            if (i < N) {
107	                SG_SANITIZE_GRAD_INPLACE(grad, i);
108	                grokadamw_step(param, exp_avg, exp_avg_sq, ema, grad,
109	                               alpha, lamb, lr, beta1, beta2, eps, wd,
110	                               bc1, bc2, i);
111	            }
112	        }
113	    }
114	}
