116	// FP32 vec4 fast path: float4 global traffic, canonical step CALLED 4×.
117	__global__ void __launch_bounds__(SG_TUNED_BLOCK_SIZE, SG_GROKADAMW_MIN_BLOCKS)
118	grokadamw_kernel_vec4_fp32(
119	    float4* param4, float4* exp_avg4, float4* exp_avg_sq4, float4* ema4,
120	    const float4* grad4,
121	    float alpha, float lamb,
122	    float lr, float beta1, float beta2, float eps, float wd,
123	    float bc1, float bc2, int64_t N4
124	) {
125	    const int64_t stride = prim::grid_stride();
126	    for (int64_t i = prim::grid_stride_index(); i < N4; i += stride) {
127	        float4 p = prim::ld_f32v4(param4 + i);
128	        float4 m = prim::ld_f32v4(exp_avg4 + i);
129	        float4 v = prim::ld_f32v4(exp_avg_sq4 + i);
130	        float4 e = prim::ld_f32v4(ema4 + i);
131	        float4 g = prim::ldg_f32v4(grad4 + i);
132	        ::grokking::sm90::sg_sanitize_grad4(g);
133	        #pragma unroll
134	        for (int u = 0; u < 4; ++u) {
135	            grokadamw_step(&p.x, &m.x, &v.x, &e.x, &g.x,
136	                           alpha, lamb, lr, beta1, beta2, eps, wd,
137	                           bc1, bc2, u);
138	        }
139	        prim::st_f32v4(param4 + i, p);
140	        prim::st_f32v4(exp_avg4 + i, m);
141	        prim::st_f32v4(exp_avg_sq4 + i, v);
142	        prim::st_f32v4(ema4 + i, e);
143	    }
144	}
