146	void launch_grokadamw_step(
147	    torch::Tensor& param,
148	    torch::Tensor& exp_avg,
149	    torch::Tensor& exp_avg_sq,
150	    torch::Tensor& ema,
151	    const torch::Tensor& grad,
152	    float alpha, float lamb,
153	    float lr, float beta1, float beta2, float eps, float wd,
154	    float bc1, float bc2
155	) {
156	    const int64_t N = param.numel();
157	    if (N == 0) return;
158	
159	    auto stream = at::cuda::getCurrentCUDAStream().stream();
160	
161	    // §6.1: keep the Adam moments (m, v) L2-resident across the step.
162	    prim::L2PersistScope l2(stream,
163	        exp_avg.data_ptr(), exp_avg.nbytes(),
164	        exp_avg_sq.data_ptr(), exp_avg_sq.nbytes());
165	
166	    const int block = SG_TUNED_BLOCK_SIZE;
167	    const int grid = static_cast<int>(
168	        std::min<int64_t>(65535, (N + block - 1) / block));
169	
170	    const bool all_fp32 = param.scalar_type() == torch::kFloat32 &&
171	                          grad.scalar_type() == torch::kFloat32;
172	
173	    if (SG_TUNED_VEC_WIDTH == 4 && all_fp32 &&
174	        prim::is_vec4_alignable(param.data_ptr(), N) &&
175	        prim::is_vec4_alignable(exp_avg.data_ptr(), N) &&
176	        prim::is_vec4_alignable(exp_avg_sq.data_ptr(), N) &&
177	        prim::is_vec4_alignable(ema.data_ptr(), N) &&
178	        prim::is_vec4_alignable(grad.data_ptr(), N)) {
179	        const int64_t N4 = N / 4;
180	        const int grid4 = static_cast<int>(
181	            std::min<int64_t>(65535, (N4 + block - 1) / block));
182	        grokadamw_kernel_vec4_fp32<<<grid4, block, 0, stream>>>(
183	            reinterpret_cast<float4*>(param.data_ptr<float>()),
184	            reinterpret_cast<float4*>(exp_avg.data_ptr<float>()),
185	            reinterpret_cast<float4*>(exp_avg_sq.data_ptr<float>()),
186	            reinterpret_cast<float4*>(ema.data_ptr<float>()),
187	            reinterpret_cast<const float4*>(grad.data_ptr<float>()),
188	            alpha, lamb, lr, beta1, beta2, eps, wd, bc1, bc2, N4);
189	        SG_LAUNCH_CHECK(stream);
190	        return;
191	    }
192	
193	    AT_DISPATCH_FLOATING_TYPES_AND2(
194	        at::ScalarType::Half, at::ScalarType::BFloat16,
195	        param.scalar_type(), "grokadamw_step", [&] {
196	            grokadamw_kernel<scalar_t, scalar_t, SG_TUNED_UNROLL>
197	                <<<grid, block, 0, stream>>>(
198	                param.data_ptr<scalar_t>(),
199	                exp_avg.data_ptr<float>(),
200	                exp_avg_sq.data_ptr<float>(),
201	                ema.data_ptr<float>(),
202	                grad.data_ptr<scalar_t>(),
203	                alpha, lamb, lr, beta1, beta2, eps, wd, bc1, bc2, N);
204	            SG_LAUNCH_CHECK(stream);
205	        });
206	}
