222	void launch_fused_grokadamw_clip_step(
223	    torch::Tensor param, torch::Tensor exp_avg, torch::Tensor exp_avg_sq,
224	    torch::Tensor ema, torch::Tensor grad,
225	    float alpha, float lamb,
226	    float beta1, float beta2,
227	    float lr, float weight_decay, float eps,
228	    float bc1, float bc2, float clip_threshold
229	) {
230	    if (clip_threshold > 0.0f) {
231	        auto gn = grad.norm().item<float>();
232	        if (gn > clip_threshold) {
233	            grad = grad.mul(clip_threshold / gn);
234	        }
235	    }
236	    launch_grokadamw_step(param, exp_avg, exp_avg_sq, ema, grad,
237	                          alpha, lamb, lr, beta1, beta2, eps, weight_decay,
238	                          bc1, bc2);
239	}
