241	// Quantized Config-3: INT8 exp_avg, BF16 exp_avg_sq & ema.
242	// Dequantize → update in FP32 → re-quantize with stochastic rounding.
243	template <typename ParamT, typename GradT>
244	__global__ void grokadamw_q3_kernel(
245	    ParamT* param,
246	    int8_t* ea_int8, float* ea_scales,
247	    __nv_bfloat16* eas_bf16, __nv_bfloat16* ema_bf16,
248	    const GradT* grad,
249	    float alpha, float lamb,
250	    float lr, float beta1, float beta2, float eps, float wd,
251	    float bc1, float bc2, unsigned step, int64_t N, int block_size
252	) {
253	    const int64_t stride = prim::grid_stride();
254	    for (int64_t i = prim::grid_stride_index(); i < N; i += stride) {
255	        int64_t scale_idx = i / block_size;
256	        float scale = ea_scales[scale_idx];
257	        float ea_val = static_cast<float>(ea_int8[i]) * scale;
258	        float eas_val = __bfloat162float(eas_bf16[i]);
259	        float ema_val = __bfloat162float(ema_bf16[i]);
260	
261	        float g = ::grokking::sm90::sg_sanitize_grad(static_cast<float>(grad[i]));
262	        float p = static_cast<float>(param[i]);
263	
264	        float ema_new = alpha * ema_val + (1.0f - alpha) * g;
265	        float g_amp = g + lamb * ema_new;
266	        // Canonical bias-corrected Adam tail (single-source: algorithms/grokadamw.h).
267	        // g_eff = g_amp; moments come from the dequantized state, results are
268	        // re-quantized below — the float math itself lives once in the header.
269	        float m, v, p_new;
270	        grokadamw_adam_tail(g_amp, p, ea_val, eas_val,
271	                            lr, beta1, beta2, eps, wd, bc1, bc2,
272	                            m, v, p_new);
273	        param[i] = static_cast<ParamT>(p_new);
274	
275	        unsigned rng = hash_prng(step, static_cast<unsigned>(i));
276	        ea_int8[i] = ptx_int8_stochastic_round(m, scale, rng);
277	        eas_bf16[i] = float_to_bf16_stochastic(v, rng >> 16);
278	        ema_bf16[i] = float_to_bf16_stochastic(ema_new, rng ^ 0xDEADBEEFu);
279	    }
280	}
