282	void launch_fused_grokadamw_step_q3(
283	    torch::Tensor param,
284	    torch::Tensor exp_avg_int8, torch::Tensor exp_avg_scales,
285	    torch::Tensor exp_avg_sq_bf16, torch::Tensor ema_bf16,
286	    torch::Tensor grad,
287	    float alpha, float lamb,
288	    float beta1, float beta2,
289	    float lr, float weight_decay, float eps,
290	    float bc1, float bc2, unsigned global_step
291	) {
292	    const int64_t N = param.numel();
293	    if (N == 0) return;
294	
295	    auto stream = at::cuda::getCurrentCUDAStream().stream();
296	    const int block = SG_TUNED_BLOCK_SIZE;
297	    const int grid = static_cast<int>(
298	        std::min<int64_t>(65535, (N + block - 1) / block));
299	    // CEIL division: the kernel indexes ea_scales[i / q_block_size] for
300	    // i in [0, N). With floor division, a non-divisible N (N % numel != 0)
301	    // makes q_block_size too small so the largest i maps to scale_idx == numel
302	    // (one past the end → OOB read). ceil(N/numel) guarantees i/q_block_size
303	    // <= numel-1 for every i < N.
304	    const int q_block_size = std::max<int>(1, static_cast<int>(
305	        (N + exp_avg_scales.numel() - 1) / exp_avg_scales.numel()));
306	
307	    AT_DISPATCH_FLOATING_TYPES_AND2(
308	        at::ScalarType::Half, at::ScalarType::BFloat16,
309	        param.scalar_type(), "grokadamw_q3", [&] {
310	            grokadamw_q3_kernel<scalar_t, scalar_t><<<grid, block, 0, stream>>>(
311	                param.data_ptr<scalar_t>(),
312	                exp_avg_int8.data_ptr<int8_t>(),
313	                exp_avg_scales.data_ptr<float>(),
314	                reinterpret_cast<__nv_bfloat16*>(exp_avg_sq_bf16.data_ptr()),
315	                reinterpret_cast<__nv_bfloat16*>(ema_bf16.data_ptr()),
316	                grad.data_ptr<scalar_t>(),
317	                alpha, lamb, lr, beta1, beta2, eps, weight_decay,
318	                bc1, bc2, global_step, N, q_block_size);
319	            SG_LAUNCH_CHECK(stream);
320	        });
321	}
