342	// AdamW is GrokAdamW with lamb=0 (EMA amplification disabled).
343	// The ema buffer is not needed; allocate a dummy per-tensor.
344	void launch_fused_adamw_simple(
345	    std::vector<torch::Tensor>& params,
346	    std::vector<torch::Tensor>& exp_avgs,
347	    std::vector<torch::Tensor>& exp_avg_sqs,
348	    std::vector<torch::Tensor>& grads,
349	    std::vector<int64_t>& steps,
350	    float beta1, float beta2, float lr, float wd, float eps
351	) {
352	    for (size_t t = 0; t < params.size(); t++) {
353	        const int64_t N = params[t].numel();
354	        if (N == 0 || !grads[t].defined()) continue;
355	        float bc1 = 1.0f - std::pow(beta1, static_cast<float>(steps[t]));
356	        float bc2 = 1.0f - std::pow(beta2, static_cast<float>(steps[t]));
357	        auto ema_dummy = torch::zeros_like(exp_avgs[t]);
358	        launch_grokadamw_step(params[t], exp_avgs[t], exp_avg_sqs[t],
359	                              ema_dummy, grads[t],
360	                              0.0f, 0.0f, lr, beta1, beta2, eps, wd,
361	                              bc1, bc2);
362	    }
363	}
